styles:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Inter',sans-serif;background:#fff;color:#1c1917;overflow-x:hidden;line-height:1.6}
img{max-width:100%;display:block}
a{text-decoration:none}
#scroll-progress{position:fixed;top:0;left:0;width:0%;height:3px;background:linear-gradient(to right,#fbbf24,#78716c,#34d399);z-index:9999;transition:width .1s linear}
header{position:fixed;top:3px;left:0;right:0;z-index:1000;transition:all .5s ease;background:#262626}
header.scrolled{background:rgba(255,255,255,.97);backdrop-filter:blur(20px);box-shadow:0 4px 32px rgba(0,0,0,.12);border-bottom:1px solid rgba(214,211,209,.5)}
.header-inner{max-width:1280px;margin:0 auto;padding:1rem 1.5rem;display:flex;align-items:center;justify-content:space-between}
.logo{display:flex;align-items:center;gap:.75rem;cursor:pointer}
.logo-icon{padding:.625rem;border-radius:1rem;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);transition:all .3s}
header.scrolled .logo-icon{background:linear-gradient(135deg,#44403c,#1e293b);border:none}
.logo-icon svg{width:1.5rem;height:1.5rem}
.logo-icon svg path{stroke:#fff}
.logo-name{font-size:1.125rem;font-weight:700;color:#fff;transition:color .3s;line-height:1.2}
header.scrolled .logo-name{color:#1c1917}
.logo-sub{font-size:.7rem;font-weight:500;color:#d6d3d1;transition:color .3s}
header.scrolled .logo-sub{color:#78716c}
nav{display:flex;align-items:center;gap:2rem}
nav a{font-weight:600;font-size:.925rem;color:#fff;transition:color .3s;position:relative}
header.scrolled nav a{color:#44403c}
nav a::after{content:'';position:absolute;bottom:-2px;left:0;width:0;height:2px;transition:width .3s}
header.scrolled nav a::after{background:#1c1917}
header:not(.scrolled) nav a::after{background:#fff}
nav a:hover::after{width:100%}
.nav-cta{display:flex;align-items:center;gap:.4rem;padding:.625rem 1.25rem;background:linear-gradient(135deg,#22c55e,#10b981);color:#fff!important;border-radius:1rem;font-weight:600;font-size:.875rem;transition:all .3s;box-shadow:0 4px 16px rgba(34,197,94,.3)}
.nav-cta:hover{background:linear-gradient(135deg,#16a34a,#059669);transform:translateY(-2px)}
.nav-cta::after{display:none!important}
.hamburger{display:none;flex-direction:column;gap:5px;cursor:pointer;padding:.5rem;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);border-radius:.75rem}
header.scrolled .hamburger{background:#f5f5f4;border-color:transparent}
.hamburger span{width:20px;height:2px;background:#fff;border-radius:2px;transition:all .3s}
header.scrolled .hamburger span{background:#1c1917}
.mobile-nav{display:none;padding:1rem 0;border-top:1px solid rgba(255,255,255,.2);margin-top:.75rem}
header.scrolled .mobile-nav{border-color:#e7e5e4}
.mobile-nav.open{display:block}
.mobile-nav a{display:block;padding:.75rem 1rem;color:#fff;font-weight:600;border-radius:.75rem;transition:all .2s}
header.scrolled .mobile-nav a{color:#44403c}
.mobile-cta{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:1rem;background:linear-gradient(135deg,#22c55e,#10b981);color:#fff!important;border-radius:1rem;font-weight:600;margin-top:.75rem}
@media(max-width:768px){nav{display:none}.hamburger{display:flex}}
.hero-image{position:relative;height:260px;overflow:hidden;margin-top:3px}
@media(min-width:768px){.hero-image{height:420px}}
.hero-image img{width:100%;height:100%;object-fit:cover;object-position:center}
.hero-overlay{position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.75) 0%,rgba(0,0,0,.35) 50%,transparent 100%)}
.hero-badge{position:absolute;bottom:1.5rem;left:1.5rem;padding:.25rem .75rem;background:rgba(255,255,255,.92);backdrop-filter:blur(8px);color:#1c1917;border-radius:9999px;font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em}
.page-wrap{max-width:80rem;margin:0 auto;padding:3rem 1.5rem}
.back-btn{display:inline-flex;align-items:center;gap:.5rem;color:#78716c;font-size:.875rem;font-weight:500;margin-bottom:2rem;transition:all .2s;cursor:pointer;background:none;border:none}
.back-btn:hover{color:#1c1917;transform:translateX(-4px)}
.back-btn svg{width:1rem;height:1rem}
.content-layout{display:flex;flex-direction:column;gap:3rem}
@media(min-width:1024px){.content-layout{flex-direction:row;align-items:flex-start}}
.sidebar{width:100%}
@media(min-width:1024px){.sidebar{width:18rem;flex-shrink:0;position:sticky;top:7rem}}
.toc{background:#fafaf9;border:1px solid #e7e5e4;border-radius:1rem;padding:1.5rem;margin-bottom:1.5rem}
.toc-header{display:flex;align-items:center;gap:.5rem;margin-bottom:1rem}
.toc-header svg{width:1.25rem;height:1.25rem;color:#78716c}
.toc-header span{font-weight:700;color:#1c1917;font-size:.8125rem;text-transform:uppercase;letter-spacing:.05em}
.toc nav ul{list-style:none}
.toc nav li{margin-bottom:.125rem}
.toc nav li.toc-h3{padding-left:1rem}
.toc nav a{display:block;padding:.375rem .75rem;border-radius:.75rem;font-size:.8125rem;color:#57534e;transition:all .2s;font-weight:500}
.toc nav a:hover{color:#1c1917;background:#e7e5e4}
.toc nav a.active{background:#1c1917;color:#fff;font-weight:600}
.toc nav .toc-h3 a{color:#78716c}
.toc nav .toc-h3 a::before{content:'› ';color:#a8a29e}
.author-box{background:#1c1917;border-radius:1rem;padding:1.5rem;color:#fff;margin-bottom:1.5rem}
.author-avatar{width:3rem;height:3rem;background:#fbbf24;border-radius:9999px;display:flex;align-items:center;justify-content:center;font-size:1.125rem;font-weight:700;color:#1c1917;margin-bottom:.75rem}
.author-name{font-weight:700;margin-bottom:.25rem}
.author-desc{color:#a8a29e;font-size:.75rem;line-height:1.5}
.share-box{background:#f5f5f4;border-radius:1rem;padding:1.25rem;text-align:center}
.share-box p{font-size:.8125rem;font-weight:600;color:#57534e;margin-bottom:.75rem;text-transform:uppercase;letter-spacing:.05em}
.share-btns{display:flex;gap:.5rem;justify-content:center}
.share-btn{padding:.5rem 1rem;border-radius:.75rem;font-size:.75rem;font-weight:600;color:#fff;border:none;cursor:pointer;transition:all .2s}
.share-wa{background:#22c55e}.share-wa:hover{background:#16a34a}
.share-tw{background:#1d9bf0}.share-tw:hover{background:#1a8cd8}
.share-li{background:#0a66c2}.share-li:hover{background:#084d92}
article{flex:1;min-width:0}
.post-meta{display:flex;flex-wrap:wrap;gap:1rem;margin-bottom:1.5rem;font-size:.875rem;color:#78716c}
.post-meta span{display:flex;align-items:center;gap:.25rem}
.post-meta svg{width:1rem;height:1rem}
.post-title{font-size:clamp(1.75rem,4vw,3rem);font-weight:800;color:#1c1917;line-height:1.2;margin-bottom:1.25rem}
.post-excerpt{font-size:1.125rem;color:#78716c;line-height:1.75;border-left:4px solid #fbbf24;padding-left:1rem;margin-bottom:2rem}
.tags{display:flex;flex-wrap:wrap;gap:.5rem;margin-bottom:2.5rem}
.tag{display:inline-flex;align-items:center;gap:.25rem;padding:.25rem .75rem;background:#f5f5f4;color:#57534e;border-radius:9999px;font-size:.75rem;font-weight:500}
.tag svg{width:.75rem;height:.75rem}
.prose h2{font-size:1.5rem;font-weight:700;color:#1c1917;margin-top:2.5rem;margin-bottom:1rem;padding-bottom:.5rem;border-bottom:1px solid #f5f5f4;scroll-margin-top:6rem}
.prose h3{font-size:1.25rem;font-weight:700;color:#292524;margin-top:2rem;margin-bottom:.75rem;scroll-margin-top:6rem}
.prose p{color:#44403c;line-height:1.75;margin-bottom:1rem;font-size:1rem}
.prose ul{list-style:disc;padding-left:1.5rem;margin-bottom:1rem;color:#44403c}
.prose ol{list-style:decimal;padding-left:1.5rem;margin-bottom:1rem;color:#44403c}
.prose li{line-height:1.75;margin-bottom:.5rem}
.prose strong{font-weight:700;color:#1c1917}
.prose em{font-style:italic}
.prose blockquote{border-left:4px solid #fbbf24;padding:.75rem 1rem;margin:1.5rem 0;background:#fffbeb;border-radius:0 .75rem .75rem 0;color:#44403c;font-style:italic}
.prose hr{margin:2rem 0;border:none;border-top:1px solid #e7e5e4}
.prose .table-wrap{overflow-x:auto;border-radius:1rem;border:1px solid #e7e5e4;box-shadow:0 4px 16px rgba(0,0,0,.06);margin:1.5rem 0}
.prose table{width:100%;font-size:.875rem;border-collapse:collapse}
.prose thead{background:#1c1917;color:#fff}
.prose th{padding:.75rem 1rem;text-align:left;font-weight:700;white-space:nowrap}
.prose tbody tr{border-top:1px solid #f5f5f4}
.prose tbody tr:hover{background:rgba(251,191,36,.06)}
.prose tbody tr:nth-child(even){background:#fafaf9}
.prose td{padding:.75rem 1rem;color:#44403c;vertical-align:top}
.prose code{background:#f5f5f4;padding:.15rem .4rem;border-radius:.375rem;font-size:.875rem;font-family:monospace;color:#1c1917}
.ah-btn{display:inline-flex;align-items:center;gap:.4rem;padding:.45rem 1rem;background:linear-gradient(135deg,#1c1917,#1e293b);color:#fff!important;border-radius:.75rem;font-weight:700;font-size:.875rem;text-decoration:none!important;transition:all .25s;box-shadow:0 4px 14px rgba(0,0,0,.18);vertical-align:middle;white-space:nowrap}
.ah-btn:hover{background:linear-gradient(135deg,#292524,#1e3a5f);transform:translateY(-2px);box-shadow:0 8px 22px rgba(0,0,0,.22)}
.ah-btn svg{width:.875rem;height:.875rem;flex-shrink:0;stroke:#fff}
.tip-box{display:flex;gap:1rem;padding:1.25rem;background:#fffbeb;border:1px solid rgba(251,191,36,.35);border-radius:1rem;margin:1.5rem 0;align-items:flex-start}
.info-box{display:flex;gap:1rem;padding:1.25rem;background:#eff6ff;border:1px solid rgba(96,165,250,.35);border-radius:1rem;margin:1.5rem 0;align-items:flex-start}
.warn-box{display:flex;gap:1rem;padding:1.25rem;background:#fef2f2;border:1px solid rgba(239,68,68,.25);border-radius:1rem;margin:1.5rem 0;align-items:flex-start}
.success-box{display:flex;gap:1rem;padding:1.25rem;background:#f0fdf4;border:1px solid rgba(34,197,94,.25);border-radius:1rem;margin:1.5rem 0;align-items:flex-start}
.box-icon{font-size:1.5rem;flex-shrink:0;line-height:1}
.tip-box p,.info-box p,.warn-box p,.success-box p{color:#44403c;font-size:.9375rem;line-height:1.65;margin:0}
.tip-box strong,.info-box strong,.warn-box strong,.success-box strong{color:#1c1917}
.checklist{list-style:none;padding:0;margin:1rem 0}
.checklist li{display:flex;align-items:flex-start;gap:.6rem;padding:.5rem 0;border-bottom:1px solid #f5f5f4;color:#44403c;font-size:.9375rem;line-height:1.6}
.checklist li:last-child{border-bottom:none}
.checklist li::before{content:'✓';color:#22c55e;font-weight:700;flex-shrink:0;margin-top:.05rem}
.step-cards{display:flex;flex-direction:column;gap:1.25rem;margin:1.5rem 0}
.step-card{border-radius:1rem;padding:1.5rem;border:1px solid #e7e5e4;background:#fafaf9;display:flex;gap:1rem;transition:box-shadow .2s}
.step-card:hover{box-shadow:0 6px 24px rgba(0,0,0,.08)}
.step-num{width:2.25rem;height:2.25rem;min-width:2.25rem;background:#1c1917;color:#fbbf24;border-radius:.75rem;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:1rem}
.step-body h4{font-weight:700;color:#1c1917;margin-bottom:.35rem}
.step-body p{color:#44403c;font-size:.9375rem;line-height:1.6;margin:0}
.step-body ul{color:#44403c;font-size:.9375rem;padding-left:1.25rem;margin:.5rem 0 0}
.step-body li{margin-bottom:.25rem;line-height:1.6}
.grid-2{display:grid;grid-template-columns:1fr;gap:1rem;margin:1.5rem 0}
@media(min-width:640px){.grid-2{grid-template-columns:repeat(2,1fr)}}
.grid-3{display:grid;grid-template-columns:1fr;gap:1rem;margin:1.5rem 0}
@media(min-width:640px){.grid-3{grid-template-columns:repeat(2,1fr)}}
@media(min-width:900px){.grid-3{grid-template-columns:repeat(3,1fr)}}
.card{background:#fafaf9;border:1px solid #e7e5e4;border-radius:1rem;padding:1.25rem;transition:box-shadow .2s,transform .2s}
.card:hover{box-shadow:0 6px 24px rgba(0,0,0,.08);transform:translateY(-2px)}
.card-icon{width:2.5rem;height:2.5rem;background:linear-gradient(135deg,#fbbf24,#f59e0b);border-radius:.75rem;display:flex;align-items:center;justify-content:center;margin-bottom:.75rem;font-size:1.25rem}
.card h4{font-weight:700;color:#1c1917;font-size:.9375rem;margin-bottom:.375rem}
.card p{color:#57534e;font-size:.8125rem;line-height:1.55;margin:0}
.card-label{display:inline-block;padding:.2rem .6rem;background:#1c1917;color:#fbbf24;border-radius:.5rem;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;margin-bottom:.6rem}
.vs-box{display:grid;grid-template-columns:1fr;gap:1.5rem;margin:1.5rem 0}
@media(min-width:640px){.vs-box{grid-template-columns:1fr 1fr}}
.vs-left{background:#eff6ff;border:1px solid rgba(96,165,250,.3);border-radius:1rem;padding:1.25rem}
.vs-right{background:#fef3c7;border:1px solid rgba(251,191,36,.35);border-radius:1rem;padding:1.25rem}
.vs-green{background:#f0fdf4;border:1px solid rgba(34,197,94,.25);border-radius:1rem;padding:1.25rem}
.vs-left h4{color:#1e40af;font-weight:700;font-size:1rem;margin-bottom:.75rem}
.vs-right h4{color:#92400e;font-weight:700;font-size:1rem;margin-bottom:.75rem}
.vs-green h4{color:#166534;font-weight:700;font-size:1rem;margin-bottom:.75rem}
.vs-left ul,.vs-right ul,.vs-green ul{list-style:disc;padding-left:1.25rem;color:#44403c;font-size:.9rem}
.vs-left li,.vs-right li,.vs-green li{margin-bottom:.35rem;line-height:1.55}
.highlight-box{background:linear-gradient(135deg,#1c1917,#1e293b);border-radius:1rem;padding:1.5rem;margin:1.5rem 0;color:#fff}
.highlight-box h4{color:#fbbf24;font-weight:700;margin-bottom:.5rem}
.highlight-box p{color:#d6d3d1;font-size:.9375rem;line-height:1.65;margin:0}
.highlight-box ul{color:#d6d3d1;font-size:.9375rem;padding-left:1.25rem;margin:.5rem 0 0}
.highlight-box li{margin-bottom:.35rem;line-height:1.6}
.faq-item{border:1px solid #e7e5e4;border-radius:1rem;margin-bottom:.75rem;overflow:hidden}
.faq-q{padding:1rem 1.25rem;font-weight:700;color:#1c1917;cursor:pointer;display:flex;justify-content:space-between;align-items:center;background:#fafaf9;user-select:none}
.faq-q::after{content:'+';font-size:1.25rem;color:#78716c;transition:transform .2s}
.faq-item.open .faq-q::after{content:'−'}
.faq-a{display:none;padding:1rem 1.25rem;color:#44403c;font-size:.9375rem;line-height:1.7;border-top:1px solid #e7e5e4}
.faq-item.open .faq-a{display:block}
.cta-box{margin:3rem 0;padding:2.5rem 2rem;background:linear-gradient(135deg,#1c1917 0%,#1e293b 50%,#1c1917 100%);border-radius:1.5rem;text-align:center;color:#fff}
.cta-box h3{font-size:1.5rem;font-weight:700;margin-bottom:.75rem}
.cta-box p{color:#d6d3d1;margin-bottom:1.5rem}
.cta-buttons{display:flex;flex-wrap:wrap;gap:1rem;justify-content:center}
.cta-btn-primary{padding:.75rem 1.5rem;background:#22c55e;color:#fff;border-radius:1rem;font-weight:600;transition:background .2s}
.cta-btn-primary:hover{background:#16a34a}
.cta-btn-secondary{padding:.75rem 1.5rem;background:rgba(255,255,255,.15);color:#fff;border-radius:1rem;font-weight:600;transition:background .2s}
.cta-btn-secondary:hover{background:rgba(255,255,255,.25)}
.related{margin-top:4rem}
.related h3{font-size:1.5rem;font-weight:700;color:#1c1917;margin-bottom:2rem}
.related-grid{display:grid;grid-template-columns:1fr;gap:1.5rem}
@media(min-width:768px){.related-grid{grid-template-columns:repeat(2,1fr)}}
.related-card{background:#fafaf9;border-radius:1rem;overflow:hidden;cursor:pointer;transition:box-shadow .3s;display:block}
.related-card:hover{box-shadow:0 8px 32px rgba(0,0,0,.12)}
.related-card img{width:100%;height:9rem;object-fit:cover;transition:transform .3s}
.related-card:hover img{transform:scale(1.05)}
.related-card-body{padding:1rem}
.related-card h4{font-weight:700;color:#1c1917;font-size:.875rem;margin-bottom:.25rem;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.related-card span{font-size:.75rem;color:#78716c}
footer{background:linear-gradient(135deg,#1c1917 0%,#1e293b 50%,#1c1917 100%);color:#fff;position:relative;overflow:hidden}
footer::before{content:'';position:absolute;top:5rem;left:5rem;width:24rem;height:24rem;background:radial-gradient(circle,rgba(251,191,36,.08) 0%,transparent 70%);pointer-events:none}
footer::after{content:'';position:absolute;bottom:5rem;right:5rem;width:24rem;height:24rem;background:radial-gradient(circle,rgba(96,165,250,.07) 0%,transparent 70%);pointer-events:none}
.footer-inner{max-width:1280px;margin:0 auto;padding:5rem 1.5rem 2rem;position:relative;z-index:1}
.footer-grid{display:grid;grid-template-columns:1fr;gap:3rem;margin-bottom:4rem}
@media(min-width:768px){.footer-grid{grid-template-columns:1fr 1fr}}
@media(min-width:1024px){.footer-grid{grid-template-columns:2fr 1fr 1fr}}
.footer-logo{display:flex;align-items:center;gap:.75rem;margin-bottom:1.5rem}
.footer-logo-icon{padding:.75rem;background:linear-gradient(135deg,#44403c,#1e293b);border-radius:1rem}
.footer-logo-icon svg{width:1.75rem;height:1.75rem}
.footer-logo-icon svg path{stroke:#fff}
.footer-brand h2{font-size:1.5rem;font-weight:700}
.footer-tagline{font-size:.875rem;color:#a8a29e;font-weight:500}
.footer-brand p{color:#d6d3d1;line-height:1.7;font-weight:300;font-size:1.0625rem;max-width:28rem;margin-bottom:1.5rem}
.footer-btns{display:flex;flex-wrap:wrap;gap:1rem}
.footer-wa{display:inline-flex;align-items:center;gap:.5rem;padding:.625rem 1.25rem;background:linear-gradient(135deg,#22c55e,#10b981);color:#fff;border-radius:1rem;font-weight:600;font-size:.875rem;transition:all .3s}
.footer-wa:hover{background:linear-gradient(135deg,#16a34a,#059669);transform:translateY(-2px)}
.footer-email{display:inline-flex;align-items:center;gap:.5rem;padding:.625rem 1.25rem;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);color:#fff;border-radius:1rem;font-weight:600;font-size:.875rem;transition:all .3s}
.footer-email:hover{background:rgba(255,255,255,.18)}
.footer-col h3{font-size:1.125rem;font-weight:700;margin-bottom:1.5rem}
.footer-col ul{list-style:none}
.footer-col ul li{margin-bottom:1rem}
.footer-col ul li a{color:#d6d3d1;font-weight:500;font-size:.9375rem;transition:color .2s;display:flex;align-items:center;gap:.5rem}
.footer-col ul li a:hover{color:#fff;padding-left:.25rem}
.footer-bottom{border-top:1px solid rgba(87,83,78,.4);padding-top:2rem;display:flex;flex-wrap:wrap;gap:1rem;justify-content:space-between;align-items:center}
.footer-bottom p{color:#a8a29e;font-size:.875rem;font-weight:300}
.footer-links{display:flex;flex-wrap:wrap;gap:1.5rem}
.footer-links a{color:#a8a29e;font-size:.875rem;font-weight:500;transition:color .2s}
.footer-links a:hover{color:#fff;text-decoration:underline}
#fab{position:fixed;bottom:1.5rem;right:1.5rem;width:3.5rem;height:3.5rem;border-radius:9999px;background:linear-gradient(135deg,#1c1917,#1e293b);color:#fff;box-shadow:0 8px 32px rgba(0,0,0,.3);display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:900;border:none;opacity:0;transform:translateY(20px) scale(.8);transition:opacity .3s,transform .3s}
#fab.visible{opacity:1;transform:translateY(0) scale(1)}
#fab:hover{transform:scale(1.1)}
#fab svg{width:1.5rem;height:1.5rem}
#fab-dot{position:absolute;top:-2px;right:-2px;width:1rem;height:1rem;background:#ef4444;border-radius:9999px}
#chat-widget{position:fixed;bottom:6.5rem;right:1.5rem;width:20rem;max-width:calc(100vw - 3rem);z-index:950;background:#fff;border-radius:1.5rem;box-shadow:0 16px 64px rgba(0,0,0,.18);border:1px solid #e7e5e4;overflow:hidden;opacity:0;transform:translateY(20px) scale(.9);transition:opacity .3s,transform .3s;pointer-events:none}
#chat-widget.open{opacity:1;transform:translateY(0) scale(1);pointer-events:all}
.chat-header{background:linear-gradient(135deg,#1c1917,#1e293b);padding:1rem;display:flex;align-items:center;justify-content:space-between}
.chat-header-left{display:flex;align-items:center;gap:.75rem}
.chat-header-icon{padding:.5rem;background:rgba(255,255,255,.15);border-radius:.75rem}
.chat-header-icon svg{width:1.25rem;height:1.25rem;color:#fff}
.chat-title{font-weight:700;font-size:1.0625rem;color:#fff}
.chat-subtitle{font-size:.8125rem;color:#d6d3d1;font-weight:300}
