const bar=document.getElementById('scroll-progress');
window.addEventListener('scroll',function(){var h=document.body.scrollHeight-window.innerHeight;bar.style.width=h?(window.scrollY/h*100)+'%':'0%';});
const hdr=document.getElementById('site-header');
window.addEventListener('scroll',function(){hdr.classList.toggle('scrolled',window.scrollY>50);});
document.getElementById('hamburger').addEventListener('click',function(){document.getElementById('mobile-nav').classList.toggle('open');});
const fab=document.getElementById('fab'),chat=document.getElementById('chat-widget');
