document.querySelectorAll('.faq-q').forEach(function(btn){btn.addEventListener('click',function(){var item=this.parentElement;document.querySelectorAll('.faq-item').forEach(function(i){if(i!==item)i.classList.remove('open');});item.classList.toggle('open');});});
document.querySelectorAll('.share-btn').forEach(function(btn){btn.addEventListener('click',function(){var type=this.dataset.type,url=encodeURIComponent(window.location.href),title=encodeURIComponent(document.title),w='';if(type==='wa')w='https://wa.me/?text='+title+'%20'+url;else if(type==='tw')w='https://twitter.com/intent/tweet?text='+title+'&url='+url;else if(type==='li')w='https://www.linkedin.com/sharing/share-offsite/?url='+url;if(w)window.open(w,'_blank','width=600,height=400');});});
(function(){
  var prose=document.getElementById('article-prose'),list=document.getElementById('toc-list');
  if(!prose||!list)return;
  var hs=prose.querySelectorAll('h2,h3');
  if(hs.length<2){document.getElementById('toc-container').style.display='none';return;}
  hs.forEach(function(h){
    if(!h.id)h.id=h.textContent.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
    var li=document.createElement('li');
    if(h.tagName==='H3')li.classList.add('toc-h3');
    var a=document.createElement('a');
    a.href='#'+h.id;a.textContent=h.textContent;
    a.addEventListener('click',function(e){e.preventDefault();var t=document.getElementById(h.id);if(t)t.scrollIntoView({behavior:'smooth'});});
    li.appendChild(a);list.appendChild(li);
  });
  var obs=new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        list.querySelectorAll('a').forEach(function(a){a.classList.remove('active');});
        var ac=list.querySelector('a[href="#'+entry.target.id+'"]');
        if(ac)ac.classList.add('active');
      }
    });
  },{rootMargin:'-80px 0px -75% 0px'});
  hs.forEach(function(h){obs.observe(h);});
})();
